import{z as p,x as A,o as E,c as B,q as t,j as i,D as l,d as e,s as o,S as s,b as r}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"正则语言泵引理","description":"","frontmatter":{"title":"正则语言泵引理","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pumping-lemma-regular.md","filePath":"cs/pumping-lemma-regular.md","lastUpdated":1791413859000}'),d={name:"cs/pumping-lemma-regular.md"};function m(h,a,D,u,c,F){const n=A("Mermaid");return E(),B("div",null,[a[2]||(a[2]=t('<h1 id="正则语言泵引理" tabindex="-1">正则语言泵引理 <a class="header-anchor" href="#正则语言泵引理" aria-label="Permalink to &quot;正则语言泵引理&quot;">​</a></h1><div class="epigraph"><p>正则语言里足够长的串，必有一段可被抽成任意多次，语言仍收下；找不到这样的分解，就不是正则。</p><footer>—— 据 Bar-Hillel, Perles and Shamir, 1961；Sipser, Introduction to the Theory of Computation 整理</footer></div><p>上一课<a href="/cs/chomsky-hierarchy">Chomsky 层级</a>把正则放在 3 型，并声明负向证明留给本课。本课不重画包含链，也不重做<a href="/cs/nfa-dfa">NFA 与 DFA</a>的子集构造。缺口是：<strong>怎样证明某个具体 \\(L\\) 不是正则</strong>——泵引理是最常用的必要性质，不是刻画。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>正向：给 DFA 或正则式，即证正则。负向：语言无穷，不能逐串检查。DFA 只有 \\(|Q|\\) 个状态，长于 \\(|Q|\\) 的接受串必在某状态上循环。抽出循环对应的子串 \\(y\\)，泵 \\(xy^kz\\) 仍走同一环。若某 \\(L\\) 对一切候选分解都能找出一个 \\(k\\) 使 \\(xy^kz\\notin L\\)，则 \\(L\\) 非正则。</p><p>标准例子：\\(\\{a^nb^n\\mid n\\ge 0\\}\\)。主干 CFG 课用括号匹配当「正则做不到」的直觉；本课把这句收成引理应用，不再谈记号流。</p><h3 id="泵引理不是充要条件" tabindex="-1">泵引理不是充要条件 <a class="header-anchor" href="#泵引理不是充要条件" aria-label="Permalink to &quot;泵引理不是充要条件&quot;">​</a></h3><p>满足可泵的语言不必正则。引理是「正则 \\(\\Rightarrow\\) 可泵」。证非正则用逆否。有些非正则语言狡猾地可泵，要用 Myhill–Nerode 或封闭性，那是后课。</p><p><span class="marginnote">Bar-Hillel–Perles–Shamir 给出泵引理的经典形式。Sipser 用博弈语言：对手给 \\(p\\)，你给 \\(w\\)，对手切 \\(xyz\\)，你选 \\(k\\)。写证明时不要漏量化顺序。</span></p><p><span class="marginnote">直觉类比：DFA 只有 \\(|Q|\\) 个房间，而长串的读取要走很多步。步数一超过房间数，必然有某个房间被两次走进——两次进这房间之间的那段路就是 \\(y\\)；把这段路删掉或来回多走几遍，出发点和终点房间都不变，「接受与否」自然也不变。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>固定泵长度 \\(p\\)。选 \\(w\\in L\\)、\\(|w|\\ge p\\)（通常取最能破坏计数的那条）。对任意满足 \\(|xy|\\le p\\)、\\(|y|\\ge 1\\) 的分解，指出某个 \\(k\\)（常取 \\(0\\) 或 \\(2\\)）使 \\(xy^kz\\notin L\\)。计数论证：循环落在 \\(a\\) 段则 \\(a,b\\) 个数不再相等。</p>',12)),(E(),i(s,null,{default:l(()=>[o(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20DFA%5B%22DFA%20%E7%8A%B6%E6%80%81%E6%9C%89%E9%99%90%22%5D%20--%3E%20LOOP%5B%22%E9%95%BF%E4%B8%B2%E5%BF%85%E5%BE%AA%E7%8E%AF%22%5D%0A%20%20LOOP%20--%3E%20PUMP%5B%22xy%5Ek%20z%20%E4%BB%8D%E6%8E%A5%E5%8F%97%22%5D%0A%20%20PUMP%20--%3E%20NEG%5B%22%E7%A0%B4%E5%9D%8F%E5%88%99%E9%9D%9E%E6%AD%A3%E5%88%99%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("p",null,"不要把 \\(\\{ww\\mid w\\in\\{0,1\\}^*\\}\\) 强行用本课引理硬泵——它更自然是后课 CFL 泵或不封闭的材料。本课把 \\(a^nb^n\\) 与 \\(\\{a^{n^2}\\}\\) 一类做完即可。",-1)),a[4]||(a[4]=r("h2",{id:"机制",tabindex:"-1"},[e("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=r("p",null,[e("引理依赖"),r("strong",null,"有限记忆"),e("：循环是同一状态重访。若允许栈，同一串可以不被这段 \\(y\\) 破坏，所以 CFL 需要另一条泵引理。本课不提前写 Ogden。")],-1)),(E(),i(s,null,{default:l(()=>[o(n,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20RUN%5B%22%E8%AF%BB%E9%95%BF%E4%B8%B2%20w%20%E7%9A%84%E7%8A%B6%E6%80%81%E5%BA%8F%E5%88%97%22%5D%20--%3E%20MORE%5B%22%E6%AD%A5%E6%95%B0%E8%B6%85%E8%BF%87%E7%8A%B6%E6%80%81%E6%95%B0%20p%22%5D%0A%20%20MORE%20--%3E%20PHP%5B%22%E9%B8%BD%E7%AC%BC%E5%8E%9F%E7%90%86%20%E6%9F%90%E7%8A%B6%E6%80%81%E8%A2%AB%E9%87%8D%E8%AE%BF%22%5D%0A%20%20PHP%20--%3E%20Y%5B%22%E4%B8%A4%E6%AC%A1%E5%88%B0%E8%AE%BF%E4%B9%8B%E9%97%B4%E7%9A%84%E8%BE%93%E5%85%A5%E6%AE%B5%E5%8D%B3%20y%22%5D%0A%20%20Y%20--%3E%20CUT%5B%22%E5%88%A0%20y%20%E6%88%96%E9%87%8D%E5%A4%8D%20y%20%E8%B5%B0%E5%90%8C%E4%B8%80%E4%B8%AA%E7%8E%AF%22%5D%0A%20%20CUT%20--%3E%20ACC%5B%22%E7%BB%88%E6%AD%A2%E7%8A%B6%E6%80%81%E4%B8%8D%E5%8F%98%20%E4%BB%8D%E8%A2%AB%E6%8E%A5%E5%8F%97%22%5D%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p><span class="marginnote">上图回答「为什么长串必有可抽段」：代入数字，DFA 只有 3 个状态、输入长 10，则状态访问共 11 次、房间只有 3 间——某间必被重访。循环段 \\(y\\) 就藏在两次到访之间，\\(k=0\\)（抽掉）或 \\(k=2\\)（再走一遍）终态都不变。</span></p><p>词法器仍可识别标识符；泵的是语言类，不是「DFA 实现得笨」。有限语言都正则，泵引理对有限 \\(L\\) 真空成立（取 \\(p\\) 大于最长串）。</p><p>泵长度 \\(p\\) 依赖于语言（或 DFA 状态数），不依赖于你选的那条 \\(w\\) 之外的参数：先有 \\(p\\)，再选 \\(w\\)。写反了量化，证明是错的。词法器识别的标识符语言正则，泵不了「任意层括号」；那是下一层 CFG 的事，不要用本课引理去泵程序语法。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 Myhill–Nerode，不用封闭性证非正则（下一课最小化之后才把封闭当工具使）。不把泵引理写成算法：选 \\(w\\) 需要人。后课默认：要从正则里排除，先尝试泵；失败再换等价类。</p><p>写证明时把「存在 \\(p\\)」放在最外层，再选 \\(w\\)，再应付所有切法。量化一乱，泵引理就变成错的组合游戏。后课 Myhill–Nerode 在泵失败时接棒。</p><p><span class="marginnote">两个易踩的坑：一，泵不出去只能说明「非正则」或「工具没选对」，泵得动却<strong>不能</strong>证明正则——可泵是必要非充分；二，有限语言让引理「真空成立」（取 \\(p\\) 大于最长串即可，找不到可切的长串），所以泵引理只对无穷语言有用。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>正则 \\(\\Rightarrow\\) 长串可泵；逆否用于排除。</li><li>量化顺序是对手与你的博弈；\\(a^nb^n\\) 是标准靶。</li><li>可泵不是正则的充要条件。</li><li>出处：Bar-Hillel, Perles and Shamir, 1961；Sipser。</li></ul>',9))])}const P=p(d,[["render",m]]);export{f as __pageData,P as default};
